<dialog data-master-dialog aria-labelledby="master-dialog-title" aria-describedby="master-dialog-description" class="m-auto w-[calc(100%-2rem)] max-w-lg rounded-2xl border border-slate-200 bg-white p-6 text-slate-900 shadow-2xl backdrop:bg-slate-950/50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100">
    <form data-master-inline-form novalidate class="space-y-4">
        <div><h2 id="master-dialog-title" data-master-dialog-title class="text-lg font-semibold">Agregar opción</h2><p id="master-dialog-description" class="mt-1 text-sm text-slate-500 dark:text-slate-400">Se guardará y seleccionará en tu formulario. Los datos que escribiste se conservan.</p><p data-master-scope-message class="mt-2 text-xs text-slate-500 dark:text-slate-400"></p><p data-master-parent class="mt-2 hidden text-xs font-medium text-brand-700 dark:text-brand-300"></p></div>
        <div data-master-dialog-error hidden role="alert" class="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-950 dark:text-red-200"></div>
        <div><label for="master-option-name" class="mb-2 block text-sm font-medium">Nombre *</label><input id="master-option-name" name="nombre" required maxlength="150" class="w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm dark:border-slate-600 dark:bg-slate-900" autocomplete="off"></div>
        <div data-master-code-field hidden><label for="master-option-code" class="mb-2 block text-sm font-medium">Código *</label><input id="master-option-code" name="codigo" maxlength="40" class="w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm dark:border-slate-600 dark:bg-slate-900"></div>
        <div><label for="master-option-description" class="mb-2 block text-sm font-medium">Descripción (opcional)</label><textarea id="master-option-description" name="descripcion" rows="2" maxlength="1000" class="w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm dark:border-slate-600 dark:bg-slate-900"></textarea></div>
        <div class="flex justify-end gap-3"><button type="button" data-master-dialog-cancel class="rounded-xl border border-slate-300 px-4 py-2.5 text-sm font-semibold dark:border-slate-600">Cancelar</button><button type="submit" class="rounded-xl bg-brand-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-brand-700 disabled:opacity-60">Guardar y seleccionar</button></div>
    </form>
</dialog>
